#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto apply_op = [&](int x, int y){
        // prefix length x, suffix length y, x>0, y>0, x+y<n
        assert(x>0 && y>0 && x+y<n);
        vector<int> np;
        // suffix: p[n-y .. n-1]
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        // middle: p[x .. n-y-1]
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        // prefix: p[0 .. x-1]
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p = np;
        ops.push_back({x,y});
    };

    // Place element i+1 at position i, for i=0..n-1
    for(int i=0; i<n-2; i++){
        // Find where value (i+1) is
        int j = -1;
        for(int k=i;k<n;k++) if(p[k]==i+1){j=k;break;}
        if(j==i) continue; // already in place

        // We want to move p[j] to position i.
        // Strategy: first move target to the very end (suffix of length 1), 
        // then move it to position i.

        // Step 1: Move p[j] to position n-1
        if(j != n-1){
            // Use op with x = j+1, y = n-1-j
            // This takes prefix [0..j], middle [j+1..j], suffix [j+1..n-1]
            // Wait: x=j+1, y=n-1-j, x+y = j+1+n-1-j = n. Need x+y < n. Doesn't work.

            // Use op: x=1, y=n-1-j. Moves suffix [j+1..n-1] to front, middle [1..j] stays, prefix [0] goes to end.
            // After: [p[j+1]..p[n-1], p[1]..p[j], p[0]]. Target was at j, now at n-1-(n-1-j)+j = ... let me think.
            // New array: suffix(n-1-j elts) + middle(j elts: indices 1..j) + prefix(1 elt: index 0)
            // Target p[j] is in middle at position (n-1-j) + (j-1) = n-2. Then p[0] is at n-1.
            // Hmm, let me just use: x=j, y=n-1-j if j>0 and n-1-j>0 and j+(n-1-j)=n-1<n. Yes!
            if(j>0 && n-1-j>0){
                apply_op(j, n-1-j);
                // target was at index j. After: suffix[n-(n-1-j)..n-1]=p[j+1..n-1] then middle p[j..j] then prefix p[0..j-1]
                // target p[j] is now at position (n-1-j) + 0 = n-1-j. Hmm, not n-1.
                // Actually target is at position n-1-j (start of middle which is just p[j]).
                j = n-1-j; // update
            }
        }
        // Step 2: Move p[j] (wherever it is now) to position i
        if(j==i) continue;
        if(j>0 && j<n-1 && i==0){
            // x = j, y = n-j... no. Try x=n-1-j if valid? Just use 2-step.
        }
        // General: x=i (if i>0), y=n-j... let me just try direct placement
        int x_val = (j > i) ? j - i : 0;
        int y_val = n - j;
        // Not clean. Let me just use: x=j, y=n-1-j to cycle, repeat.
        if(p[j]!=i+1){j=-1;for(int k=i;k<n;k++)if(p[k]==i+1){j=k;break;}}
        if(j==i)continue;
        if(j<n-1 && j>i){apply_op(i?i:1, n-j);j=find(p.begin(),p.end(),i+1)-p.begin();}
        if(j!=i && j>0){apply_op(j,n-1-j>0?n-1-j:1);j=find(p.begin(),p.end(),i+1)-p.begin();}
        if(j!=i && j==0 && i>0){apply_op(i,n-i-1>0?n-i-1:1);j=find(p.begin(),p.end(),i+1)-p.begin();}
    }

    printf("%d\n",(int)ops.size());
    for(auto&[a,b]:ops) printf("%d %d\n",a,b);
}
